def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def parse_time(text):
        parts = text.split(":")
        return int(parts[0]) * 60 + int(parts[1])

    def format_time(value):
        h, m = divmod(value, 60)
        return str(h).zfill(2) + ":" + str(m).zfill(2)

    def parse_offset(text):
        sign = 1
        if text[:1] == "-":
            sign = -1
        hours = int(text[1:3])
        mins = int(text[4:6])
        return sign * (hours * 60 + mins)

    def ceil_quarter(value):
        rem = value % 15
        if rem == 0:
            return value
        return value + (15 - rem)

    def merge_intervals(intervals):
        items = []
        for start, end in sorted(intervals):
            if end <= start:
                continue
            if not items:
                items.append([start, end])
            else:
                last = items[-1]
                if start <= last[1]:
                    if end > last[1]:
                        last[1] = end
                else:
                    items.append([start, end])
        merged = []
        for start, end in items:
            merged.append((start, end))
        return merged

    def time_in_text(text):
        colon = text.find(":")
        if colon == -1:
            return -1
        left = colon - 1
        while left >= 0 and text[left].isdigit():
            left -= 1
        right = colon + 1
        while right < len(text) and text[right].isdigit():
            right += 1
        hour_text = text[left + 1:colon]
        minute_text = text[colon + 1:right]
        if len(hour_text) == 0 or len(minute_text) < 2:
            return -1
        return int(hour_text) * 60 + int(minute_text[:2])

    def day_matches(note, day):
        low = note.lower()
        if day == "mon":
            return "mon" in low
        if day == "tue":
            return "tue" in low
        if day == "wed":
            return "wed" in low
        if day == "thu":
            return "thu" in low
        if day == "fri":
            return "fri" in low
        return False

    def note_blocks(note, day):
        blocks = []
        low = note.lower()
        if ("no meeting" in low or "no-meeting" in low) and day_matches(low, day):
            blocks.append((0, 24 * 60))
        if "offline from" in low and day_matches(low, day):
            pos = low.find("offline from") + len("offline from")
            after = low[pos:]
            start = time_in_text(after)
            if start >= 0:
                blocks.append((start, 24 * 60))
        return blocks

    def load_calendar(person):
        data = api.read_calendar(person, "")
        days_map = {}
        if isinstance(data, dict):
            if "days" in data:
                for item in data.get("days", []):
                    if isinstance(item, dict):
                        day_key = item.get("day", "")
                        days_map[day_key] = item
            elif "day" in data:
                day_key = data.get("day", "")
                days_map[day_key] = data
            offset_text = data.get("utc_offset", "+00:00")
            working_text = data.get("working_hours", "09:00-17:00")
            note_text = data.get("note", "")
        else:
            offset_text = "+00:00"
            working_text = "09:00-17:00"
            note_text = ""
        work_parts = working_text.split("-")
        work_start = parse_time(work_parts[0])
        work_end = parse_time(work_parts[1])
        return {
            "days": days_map,
            "offset": parse_offset(offset_text),
            "work_start": work_start,
            "work_end": work_end,
            "note": note_text,
        }

    def free_at(calendar, day, user_start, user_end, user_offset):
        day_data = calendar["days"].get(day, {})
        delta = calendar["offset"] - user_offset
        local_start = user_start + delta
        local_end = user_end + delta

        if local_start < calendar["work_start"] or local_end > calendar["work_end"]:
            return False

        busy = []
        events = day_data.get("events", [])
        for event in events:
            if event.get("show_as", "busy") != "free":
                start = parse_time(event.get("start", "00:00"))
                end = parse_time(event.get("end", "00:00"))
                busy.append((start, end))

        busy.extend(note_blocks(calendar["note"], day))
        for start, end in merge_intervals(busy):
            if local_start < end and local_end > start:
                return False
        return True

    user_calendar = load_calendar("")
    user_offset = user_calendar["offset"]

    people = [user_calendar]
    for person in attendees:
        people.append(load_calendar(person))

    user_start_bound = user_calendar["work_start"]
    if earliest:
        user_start_bound = max(user_start_bound, parse_time(earliest))

    user_end_bound = user_calendar["work_end"] - minutes
    if latest_end:
        user_end_bound = min(user_end_bound, parse_time(latest_end) - minutes)

    user_start_bound = ceil_quarter(user_start_bound)

    result = {}
    for day in days:
        starts = []
        if user_start_bound <= user_end_bound:
            for start in range(user_start_bound, user_end_bound + 1, 15):
                end = start + minutes
                if end > user_calendar["work_end"]:
                    continue
                ok = True
                for calendar in people:
                    if not free_at(calendar, day, start, end, user_offset):
                        ok = False
                        break
                if ok:
                    starts.append(format_time(start))
        if starts:
            result[day] = starts

    return {"starts": result}
