def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def parse_time(text):
        parts = text.strip().split(":")
        return int(parts[0]) * 60 + int(parts[1])

    def fmt_time(total):
        h, m = divmod(total, 60)
        if h < 10:
            hs = "0" + str(h)
        else:
            hs = str(h)
        if m < 10:
            ms = "0" + str(m)
        else:
            ms = str(m)
        return hs + ":" + ms

    def ceil_quarter(total):
        r = total % 15
        if r == 0:
            return total
        return total + (15 - r)

    def collect_times(text):
        found = []
        digits = "0123456789"
        i = 0
        while i + 4 < len(text):
            if (
                text[i] in digits and
                text[i + 1] in digits and
                text[i + 2] == ":" and
                text[i + 3] in digits and
                text[i + 4] in digits
            ):
                found.append(text[i:i + 5])
                i += 5
            else:
                i += 1
        return found

    def parse_note(note_text, work_end):
        note_map = {}
        if not note_text:
            return note_map
        text = note_text.lower()
        if not ("offline" in text or "unavailable" in text or "busy" in text or "away" in text):
            return note_map

        times = collect_times(text)
        if len(times) == 0:
            return note_map

        start = parse_time(times[0])
        if len(times) > 1:
            end = parse_time(times[1])
        else:
            end = work_end

        if end <= start:
            end = work_end
        if end > work_end:
            end = work_end
        if start >= work_end:
            return note_map

        day_map = []
        if "weekday" in text:
            day_map = ["mon", "tue", "wed", "thu", "fri"]
        else:
            day_names = [
                ("mon", ["monday", "mondays"]),
                ("tue", ["tuesday", "tuesdays"]),
                ("wed", ["wednesday", "wednesdays"]),
                ("thu", ["thursday", "thursdays"]),
                ("fri", ["friday", "fridays"]),
            ]
            for abbr, names in day_names:
                for name in names:
                    if name in text:
                        day_map.append(abbr)
                        break

        if len(day_map) == 0:
            return note_map

        for day in day_map:
            if day in note_map:
                note_map[day].append((start, end))
            else:
                note_map[day] = [(start, end)]
        return note_map

    def get_person_data(person):
        data = api.read_calendar(person, "")
        work_hours = data.get("working_hours", "09:00-17:00")
        pieces = work_hours.split("-")
        work_start = parse_time(pieces[0])
        work_end = parse_time(pieces[1])

        note_map = parse_note(data.get("note", ""), work_end)
        day_map = {}

        for day_entry in data.get("days", []):
            key = day_entry.get("day", "").lower()
            busy = []
            for event in day_entry.get("events", []):
                if event.get("show_as") == "busy":
                    busy.append((parse_time(event.get("start", "00:00")),
                                 parse_time(event.get("end", "00:00"))))
            if key in note_map:
                for interval in note_map[key]:
                    busy.append(interval)
            day_map[key] = busy

        for key in note_map:
            if key not in day_map:
                day_map[key] = note_map[key]

        return {"work_start": work_start, "work_end": work_end, "days": day_map}

    people = []
    if "" not in people:
        people.append("")
    for name in attendees:
        if name not in people:
            people.append(name)

    info_list = []
    for person in people:
        info_list.append(get_person_data(person))

    start_floor = None
    if earliest:
        start_floor = parse_time(earliest)

    end_limit = None
    if latest_end:
        end_limit = parse_time(latest_end)

    out = {}
    for day in days:
        key = day.lower()
        common_start = None
        common_end = None
        busy_lists = []

        for info in info_list:
            ws = info["work_start"]
            we = info["work_end"]
            if common_start is None or ws > common_start:
                common_start = ws
            if common_end is None or we < common_end:
                common_end = we
            busy_lists.append(info["days"].get(key, []))

        if start_floor is None:
            start_bound = common_start
        else:
            if start_floor > common_start:
                start_bound = start_floor
            else:
                start_bound = common_start

        if end_limit is not None and end_limit < common_end:
            common_end = end_limit

        start_bound = ceil_quarter(start_bound)
        max_start = common_end - minutes
        if max_start < start_bound:
            continue

        starts = []
        current = start_bound
        while current <= max_start:
            end = current + minutes
            free = True
            for busy in busy_lists:
                for interval in busy:
                    if current < interval[1] and end > interval[0]:
                        free = False
                        break
                if not free:
                    break
            if free:
                starts.append(fmt_time(current))
            current += 15

        if len(starts) > 0:
            out[key] = starts

    return {"starts": out}
