def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def to_minutes(text):
        parts = text.split(":")
        return int(parts[0]) * 60 + int(parts[1])

    def to_text(total):
        h, m = divmod(total, 60)
        return str(h).zfill(2) + ":" + str(m).zfill(2)

    def ceil_quarter(total):
        return ((total + 14) // 15) * 15

    def find_time_after(text, start):
        for i in range(start, len(text) - 4):
            a = text[i]
            b = text[i + 1]
            c = text[i + 2]
            d = text[i + 3]
            e = text[i + 4]
            if a >= "0" and a <= "9" and b >= "0" and b <= "9" and c == ":" and d >= "0" and d <= "9" and e >= "0" and e <= "9":
                return to_minutes(text[i:i + 5])
        return None

    def note_bounds(note):
        min_start = None
        max_end = None
        s = note.lower()
        words = ["before ", "after ", "from ", "until ", "till ", "by "]
        for word in words:
            pos = 0
            while True:
                pos = s.find(word, pos)
                if pos == -1:
                    break
                t = find_time_after(s, pos + len(word))
                if t is not None:
                    prev = s[max(0, pos - 40):pos]
                    neg = prev.find("don't") != -1 or prev.find("can't") != -1 or prev.find("cannot") != -1 or prev.find(" not ") != -1 or prev.find(" no ") != -1
                    core = word.strip()
                    if core == "from":
                        if min_start is None or t > min_start:
                            min_start = t
                    elif core == "before":
                        if neg:
                            if min_start is None or t > min_start:
                                min_start = t
                        else:
                            if max_end is None or t < max_end:
                                max_end = t
                    elif core == "after":
                        if neg:
                            if max_end is None or t < max_end:
                                max_end = t
                        else:
                            if min_start is None or t > min_start:
                                min_start = t
                    else:
                        if max_end is None or t < max_end:
                            max_end = t
                pos += len(word)
        return min_start, max_end

    result = {}
    people = [""]
    for name in attendees:
        people.append(name)

    default_earliest = 0
    if earliest != "":
        default_earliest = to_minutes(earliest)

    default_latest = 24 * 60
    if latest_end != "":
        default_latest = to_minutes(latest_end)

    for day in days:
        day_start = default_earliest
        day_end = default_latest
        busy = []

        for person in people:
            data = api.read_calendar(person, day)

            hours = data.get("working_hours", "")
            if isinstance(hours, str) and hours.find("-") != -1:
                parts = hours.split("-")
                if len(parts) == 2:
                    ws = to_minutes(parts[0])
                    we = to_minutes(parts[1])
                    if ws > day_start:
                        day_start = ws
                    if we < day_end:
                        day_end = we

            note = data.get("note", "")
            if isinstance(note, str) and note != "":
                nstart, nend = note_bounds(note)
                if nstart is not None and nstart > day_start:
                    day_start = nstart
                if nend is not None and nend < day_end:
                    day_end = nend

            day_items = data.get("days", [])
            chosen = None
            if isinstance(day_items, list):
                want = day.lower()[:3]
                for item in day_items:
                    if isinstance(item, dict):
                        got = item.get("day", "")
                        if isinstance(got, str) and got.lower()[:3] == want:
                            chosen = item
                            break
                if chosen is None and len(day_items) > 0 and isinstance(day_items[0], dict):
                    chosen = day_items[0]

            if isinstance(chosen, dict):
                events = chosen.get("events", [])
                if isinstance(events, list):
                    for event in events:
                        if isinstance(event, dict):
                            show = event.get("show_as", "busy")
                            if not isinstance(show, str):
                                show = "busy"
                            if show.lower() != "free":
                                start = event.get("start", "")
                                end = event.get("end", "")
                                if isinstance(start, str) and isinstance(end, str) and start != "" and end != "":
                                    busy.append((to_minutes(start), to_minutes(end)))

        first_start = ceil_quarter(day_start)
        last_start = day_end - minutes
        starts = []

        if first_start <= last_start:
            for t in range(first_start, last_start + 1, 15):
                end_time = t + minutes
                if end_time <= day_end:
                    free = True
                    for bstart, bend in busy:
                        if t < bend and end_time > bstart:
                            free = False
                            break
                    if free:
                        starts.append(to_text(t))

        if len(starts) > 0:
            result[day] = starts

    return {"starts": result}
