def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def parse_time(text):
        if not text:
            return None
        text = text.strip()
        if len(text) < 5:
            return None
        if text[2] != ":":
            return None
        return int(text[0:2]) * 60 + int(text[3:5])

    def format_time(value):
        h = value // 60
        m = value % 60
        return str(h).rjust(2, "0") + ":" + str(m).rjust(2, "0")

    def parse_offset(text):
        if not text:
            return 0
        text = text.strip()
        sign = 1
        if text[0] == "-":
            sign = -1
        h = int(text[1:3])
        m = int(text[4:6])
        return sign * (h * 60 + m)

    def ceiling_quarter(value):
        r = value % 15
        if r == 0:
            return value
        return value + (15 - r)

    def normalize_day(text):
        return text.strip().lower()[:3]

    def first_day_key(resp, fallback):
        items = resp.get("days", [])
        if len(items) > 0:
            d = items[0].get("day", "")
            if d:
                return normalize_day(d)
        return normalize_day(fallback)

    def first_events(resp):
        items = resp.get("days", [])
        if len(items) > 0:
            evs = items[0].get("events", [])
            if evs is None:
                return []
            return evs
        return []

    def working_bounds(resp):
        wh = resp.get("working_hours", "")
        if "-" in wh:
            a, b = wh.split("-", 1)
            return parse_time(a), parse_time(b)
        return 0, 24 * 60

    def find_time_after(text, marker):
        pos = text.find(marker)
        if pos == -1:
            return None
        i = pos + len(marker)
        while i + 4 < len(text):
            if text[i].isdigit() and text[i + 1].isdigit() and text[i + 2] == ":" and text[i + 3].isdigit() and text[i + 4].isdigit():
                return int(text[i:i + 2]) * 60 + int(text[i + 3:i + 5])
            i += 1
        return None

    def note_rules(note, day_key, work_start, work_end):
        earliest_local = work_start
        latest_local = work_end
        blocked = []
        buffer = 0
        if not isinstance(note, str):
            note = ""
        low = note.lower()

        if "no-meeting wednesdays" in low or "no meeting wednesdays" in low:
            if day_key == "wed":
                return None

        if ("don't book me before" in low) or ("do not book me before" in low) or ("before" in low and "focus time" in low):
            t = find_time_after(low, "before")
            if t is not None and t > earliest_local:
                earliest_local = t

        if "offline from" in low:
            t = find_time_after(low, "offline from")
            if t is not None:
                if day_key == "mon" and "mondays" in low:
                    if t < latest_local:
                        latest_local = t
                if day_key == "tue" and "tuesdays" in low:
                    if t < latest_local:
                        latest_local = t
                if day_key == "wed" and "wednesdays" in low:
                    if t < latest_local:
                        latest_local = t
                if day_key == "thu" and "thursdays" in low:
                    if t < latest_local:
                        latest_local = t
                if day_key == "fri" and "fridays" in low:
                    if t < latest_local:
                        latest_local = t

        if "free for lunch" in low or ("lunch" in low and "12:00" in low and "13:00" in low):
            blocked.append((12 * 60, 13 * 60))

        if "leave 15 minutes between any meeting" in low:
            buffer = 15

        return earliest_local, latest_local, blocked, buffer

    def person_data(resp, fallback_day):
        day_key = first_day_key(resp, fallback_day)
        offset = parse_offset(resp.get("utc_offset", ""))
        work_start, work_end = working_bounds(resp)
        rules = note_rules(resp.get("note", ""), day_key, work_start, work_end)
        if rules is None:
            return None
        earliest_local, latest_local, blocked, buffer = rules
        intervals = []
        events = first_events(resp)
        for event in events:
            if event.get("show_as") == "busy":
                s = parse_time(event.get("start", ""))
                e = parse_time(event.get("end", ""))
                if s is not None and e is not None:
                    if buffer != 0:
                        intervals.append((s - buffer, e + buffer))
                    else:
                        intervals.append((s, e))
        for interval in blocked:
            intervals.append(interval)
        return {
            "day": day_key,
            "offset": offset,
            "work_start": work_start,
            "work_end": work_end,
            "earliest": earliest_local,
            "latest": latest_local,
            "intervals": intervals,
        }

    def overlaps(start, end, intervals):
        for a, b in intervals:
            if start < b and end > a:
                return True
        return False

    result = {}
    if len(days) == 0:
        return {"starts": result}

    earliest_limit = parse_time(earliest) if earliest else None
    latest_limit = parse_time(latest_end) if latest_end else None

    for day in days:
        user_resp = api.read_calendar("", day)
        user_info = person_data(user_resp, day)
        if user_info is None:
            continue

        people = [user_info]
        bad_day = False
        for name in attendees:
            resp = api.read_calendar(name, day)
            info = person_data(resp, day)
            if info is None:
                bad_day = True
                break
            people.append(info)
        if bad_day:
            continue

        user_start = user_info["earliest"]
        user_end = user_info["latest"]

        if earliest_limit is not None and earliest_limit > user_start:
            user_start = earliest_limit
        if latest_limit is not None and latest_limit < user_end:
            user_end = latest_limit

        start_min = ceiling_quarter(user_start)
        last_start = user_end - minutes
        if start_min > last_start:
            continue

        starts = []
        start = start_min
        while start <= last_start:
            end = start + minutes
            ok = True
            for person in people:
                local_start = start + (person["offset"] - user_info["offset"])
                local_end = end + (person["offset"] - user_info["offset"])
                if local_start < person["earliest"] or local_end > person["latest"]:
                    ok = False
                    break
                if overlaps(local_start, local_end, person["intervals"]):
                    ok = False
                    break
            if ok:
                starts.append(format_time(start))
            start += 15

        if len(starts) > 0:
            result[first_day_key(user_resp, day)] = starts

    return {"starts": result}
