def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def parse_time(text):
        parts = text.split(":")
        return int(parts[0]) * 60 + int(parts[1])

    def format_time(total):
        hour = total // 60
        minute = total % 60
        h = str(hour)
        m = str(minute)
        if len(h) == 1:
            h = "0" + h
        if len(m) == 1:
            m = "0" + m
        return h + ":" + m

    def parse_offset(text):
        sign = 1
        if text[0] == "-":
            sign = -1
        hour = int(text[1:3])
        minute = int(text[4:6])
        return sign * (hour * 60 + minute)

    def round_up_quarter(value):
        remainder = value % 15
        if remainder == 0:
            return value
        return value + (15 - remainder)

    def parse_hours(text):
        parts = text.split("-")
        return parse_time(parts[0]), parse_time(parts[1])

    def build_day_map(data):
        day_map = {}
        for item in data.get("days", []):
            day_map[item["day"]] = item.get("events", [])
        return day_map

    def parse_note_blocks(note, delta):
        blocks = {}
        if not note:
            return blocks

        text = note.lower()

        if "no-meeting wednesday" in text or "no meeting wednesday" in text:
            blocks["wed"] = [(0, 24 * 60)]

        if "offline from" in text:
            start_pos = text.find("offline from") + len("offline from")
            tail = note[start_pos:].strip()
            if len(tail) >= 5 and tail[2] == ":":
                time_min = parse_time(tail[:5]) + delta
                if time_min < 0:
                    time_min = 0
                if time_min > 24 * 60:
                    time_min = 24 * 60

                on_pos = text.find("on ", start_pos)
                if on_pos != -1:
                    days_text = text[on_pos + 3:]
                    target_days = []
                    if "monday" in days_text:
                        target_days.append("mon")
                    if "tuesday" in days_text:
                        target_days.append("tue")
                    if "wednesday" in days_text:
                        target_days.append("wed")
                    if "thursday" in days_text:
                        target_days.append("thu")
                    if "friday" in days_text:
                        target_days.append("fri")

                    for d in target_days:
                        if d in blocks:
                            blocks[d].append((time_min, 24 * 60))
                        else:
                            blocks[d] = [(time_min, 24 * 60)]
        return blocks

    user = api.read_calendar("", "")
    user_offset = parse_offset(user["utc_offset"])

    all_people = [("", user)]
    for person in attendees:
        all_people.append((person, api.read_calendar(person, "")))

    records = []
    for person, data in all_people:
        offset = parse_offset(data["utc_offset"])
        delta = user_offset - offset
        work_start, work_end = parse_hours(data["working_hours"])
        day_map = build_day_map(data)
        note_blocks = parse_note_blocks(data.get("note", ""), delta)
        records.append((delta, work_start + delta, work_end + delta, day_map, note_blocks))

    if earliest == "":
        earliest_min = 0
    else:
        earliest_min = parse_time(earliest)

    if latest_end == "":
        latest_end_min = 24 * 60
    else:
        latest_end_min = parse_time(latest_end)

    starts = {}
    for day in days:
        lower = earliest_min
        upper = latest_end_min
        busy = []

        for delta, work_start, work_end, day_map, note_blocks in records:
            if work_start > lower:
                lower = work_start
            if work_end < upper:
                upper = work_end

            events = day_map.get(day, [])
            for event in events:
                if event.get("show_as", "busy") != "free":
                    s = parse_time(event["start"]) + delta
                    e = parse_time(event["end"]) + delta
                    busy.append((s, e))

            for interval in note_blocks.get(day, []):
                busy.append(interval)

        limit = upper - minutes
        start = round_up_quarter(lower)
        workable = []

        while start <= limit:
            end = start + minutes
            ok = True
            for bstart, bend in busy:
                if start < bend and end > bstart:
                    ok = False
                    break
            if ok:
                workable.append(format_time(start))
            start += 15

        if workable:
            starts[day] = workable

    return {"starts": starts}
