def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def to_min(text):
        parts = text.split(":")
        return int(parts[0]) * 60 + int(parts[1])

    def to_time(total):
        return str(total // 60).zfill(2) + ":" + str(total % 60).zfill(2)

    def align_up(total, step):
        q, r = divmod(total, step)
        if r == 0:
            return total
        return (q + 1) * step

    def same_day(a, b):
        return str(a).lower()[:3] == str(b).lower()[:3]

    def first_time_after(text, word):
        pos = text.find(word)
        if pos < 0:
            return ""
        i = pos + len(word)
        while i + 4 < len(text):
            if (
                text[i].isdigit()
                and text[i + 1].isdigit()
                and text[i + 2] == ":"
                and text[i + 3].isdigit()
                and text[i + 4].isdigit()
            ):
                return text[i:i + 5]
            i += 1
        return ""

    def note_applies(note, day):
        if not note:
            return False
        n = note.lower()
        forms = {
            "mon": ["monday", "mondays"],
            "tue": ["tuesday", "tuesdays"],
            "wed": ["wednesday", "wednesdays"],
            "thu": ["thursday", "thursdays"],
            "fri": ["friday", "fridays"],
        }
        any_day = False
        for key in forms:
            for w in forms[key]:
                if w in n:
                    any_day = True
                    break
            if any_day:
                break
        if not any_day:
            return True
        abbr = str(day).lower()[:3]
        if abbr in forms:
            for w in forms[abbr]:
                if w in n:
                    return True
        return False

    def merge(intervals):
        ordered = sorted(intervals)
        merged = []
        for s, e in ordered:
            if s < 0:
                s = 0
            if e > 24 * 60:
                e = 24 * 60
            if s >= e:
                continue
            if not merged or s > merged[-1][1]:
                merged.append([s, e])
            else:
                if e > merged[-1][1]:
                    merged[-1][1] = e
        return merged

    result = {}
    people = [""]
    for person in attendees:
        people.append(person)

    for day in days:
        busy = []
        shared_start = 0
        shared_end = 24 * 60

        for person in people:
            resp = api.read_calendar(person, day)

            wh = resp.get("working_hours", "09:00-17:00")
            if "-" in wh:
                ws = to_min(wh.split("-")[0])
                we = to_min(wh.split("-")[1])
            else:
                ws = 0
                we = 24 * 60

            if ws > shared_start:
                shared_start = ws
            if we < shared_end:
                shared_end = we

            day_obj = None
            days_list = resp.get("days", [])
            for item in days_list:
                if same_day(item.get("day", ""), day):
                    day_obj = item
                    break
            if day_obj is None and len(days_list) > 0:
                day_obj = days_list[0]

            if day_obj is not None:
                for ev in day_obj.get("events", []):
                    show = str(ev.get("show_as", "busy")).lower()
                    if show != "free":
                        s = to_min(ev.get("start", "00:00"))
                        e = to_min(ev.get("end", "00:00"))
                        if s < ws:
                            s = ws
                        if e > we:
                            e = we
                        if s < e:
                            busy.append((s, e))

            note = resp.get("note", "")
            if note and note_applies(note, day):
                low = note.lower()

                t = first_time_after(low, "before")
                if t:
                    s = ws
                    e = to_min(t)
                    if e > we:
                        e = we
                    if s < e:
                        busy.append((s, e))

                t = first_time_after(low, "offline from")
                if t:
                    s = to_min(t)
                    if s < ws:
                        s = ws
                    e = we
                    if s < e:
                        busy.append((s, e))

        busy = merge(busy)

        start = shared_start
        if earliest:
            first = to_min(earliest)
            if first > start:
                start = first
        start = align_up(start, 15)

        limit = shared_end - minutes
        if latest_end:
            latest = to_min(latest_end)
            if latest - minutes < limit:
                limit = latest - minutes

        if start <= limit:
            starts = []
            cand = start
            while cand <= limit:
                end = cand + minutes
                ok = True
                for s, e in busy:
                    if cand < e and end > s:
                        ok = False
                        break
                if ok:
                    starts.append(to_time(cand))
                cand += 15
            if len(starts) > 0:
                result[day] = starts

    return {"starts": result}
