    def format_time(value):
        h = value // 60
        m = value % 60
        sh = str(h)
        sm = str(m)
        if h < 10:
            sh = "0" + sh
        if m < 10:
            sm = "0" + sm
        return sh + ":" + sm

    def parse_offset(text):
        sign = 1
        if text[0] == "-":
            sign = -1
        hours = int(text[1:3])
        mins = int(text[4:6])
        return sign * (hours * 60 + mins)

    def round_up_quarter(value):
        r = value % 15
        if r == 0:
            return value
        return value + (15 - r)

    def get_calendar(person):
        try:
            return api.read_calendar(person)
        except TypeError:
            try:
                return api.read_calendar(person, "")
            except TypeError:
                return api.read_calendar(person, None)

    def get_days(data):
        if isinstance(data, dict):
            if "days" in data and isinstance(data["days"], list):
                return data["days"]
            if "day" in data:
                return [data]
        return []

    def get_person_info(person):
        data = get_calendar(person)
        day_map = {}
        offset = 0
        work_start = 0
        work_end = 24 * 60
        note = ""
        if isinstance(data, dict):
            if "utc_offset" in data and isinstance(data["utc_offset"], str):
                offset = parse_offset(data["utc_offset"])
            if "working_hours" in data and isinstance(data["working_hours"], str):
                wh = data["working_hours"].split("-")
                if len(wh) == 2:
                    work_start = parse_time(wh[0].strip())
                    work_end = parse_time(wh[1].strip())
            if "note" in data and isinstance(data["note"], str):
                note = data["note"]
        for day_data in get_days(data):
            if isinstance(day_data, dict) and "day" in day_data:
                day_map[day_data["day"]] = day_data
        note_lower = note.lower()
        no_meeting_days = set()
        day_tokens = {
            "mon": ["mon", "monday", "mondays"],
            "tue": ["tue", "tues", "tuesday", "tuesdays"],
            "wed": ["wed", "weds", "wednesday", "wednesdays"],
            "thu": ["thu", "thur", "thurs", "thursday", "thursdays"],
            "fri": ["fri", "friday", "fridays"],
        }
        if "no-meeting" in note_lower or "no meeting" in note_lower:
            for d in day_tokens:
                tokens = day_tokens[d]
                for token in tokens:
                    if token in note_lower:
                        no_meeting_days.add(d)
                        break
        earliest_local = None
        if "before" in note_lower:
            after = note_lower.split("before", 1)[1].strip()
            words = after.replace(".", " ").replace(",", " ").replace(";", " ").split()
            for word in words:
                t = word.strip(".,;")
                if len(t) >= 5 and t[2] == ":":
                    try:
