                        break
                    except ValueError:
                        pass
        return {
            "offset": offset,
            "work_start": work_start,
            "work_end": work_end,
            "day_map": day_map,
            "no_meeting_days": no_meeting_days,
            "earliest_local": earliest_local,
        }

    def overlaps(a_start, a_end, b_start, b_end):
        return a_start < b_end and a_end > b_start

    people = []
    seen = set()
    if "" not in seen:
        seen.add("")
        people.append("")
    for name in attendees:
