            seen.add(name)
            people.append(name)

    infos = {}
    for person in people:
        infos[person] = get_person_info(person)

    user_info = infos[""]
    user_offset = user_info["offset"]

    global_start = user_info["work_start"]
    global_end = user_info["work_end"]
    if earliest != "":
        global_start = max(global_start, parse_time(earliest))
    if latest_end != "":
        global_end = min(global_end, parse_time(latest_end))

    scan_start = round_up_quarter(global_start)
    scan_end = global_end - minutes

    result = {}
    for day in days:
        day_key = day
        starts = []
        if scan_start <= scan_end:
            candidate = scan_start
            while candidate <= scan_end:
                ok = True
                for person in people:
                    info = infos[person]
                    delta = user_offset - info["offset"]
                    local_start = candidate - delta
                    local_end = candidate + minutes - delta

                    if local_start < info["work_start"] or local_end > info["work_end"]:
                        ok = False
                        break

                    if day_key in info["no_meeting_days"]:
                        ok = False
                        break

                    if info["earliest_local"] is not None and local_start < info["earliest_local"]:
                        ok = False
                        break

                    day_data = info["day_map"].get(day_key)
                    if day_data is not None and isinstance(day_data, dict):
                        events = day_data.get("events", [])
                        for event in events:
                            if isinstance(event, dict) and event.get("show_as") == "busy":
                                if "start" in event and "end" in event:
                                    try:
                                        event_start = parse_time(event["start"])
                                        event_end = parse_time(event["end"])
                                    except ValueError:
                                        continue
                                    if overlaps(local_start, local_end, event_start, event_end):
                                        ok = False
                                        break
                        if not ok:
                            break

                if ok:
                    starts.append(format_time(candidate))
                candidate += 15

        if len(starts) > 0:
            result[day_key] = starts

    return {"starts": result}
