def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def normday(day):
        return day.strip().lower()[:3]

    def timetominutes(t):
        p = t.strip().split(":")
        return int(p[0]) * 60 + int(p[1])

    def minutestotime(m):
        h = m // 60
        mi = m % 60
        s = ""
        if h < 10:
            s += "0"
        s += str(h)
        s += ":"
        if mi < 10:
            s += "0"
        s += str(mi)
        return s

    def ceilquarter(m):
        r = m % 15
        if r == 0:
            return m
        return m + (15 - r)

    def parseoffset(off):
        if not off:
            return 0
        sign = 1
        if off[0] == "-":
            sign = -1
        h = int(off[1:3])
        mi = int(off[4:6])
        return sign * (h * 60 + mi)

    def overlap(a1, a2, b1, b2):
        return a1 < b2 and a2 > b1

    def eventsfromresponse(resp):
        daysdata = resp.get("days", [])
        if len(daysdata) == 0:
            return []
        return daysdata[0].get("events", [])

    def userbusy(resp):
        res = []
        for ev in eventsfromresponse(resp):
            if ev.get("show_as") == "busy":
                res.append((timetominutes(ev.get("start")), timetominutes(ev.get("end"))))
        return res

    def personinfo(resp, daykey):
        off = parseoffset(resp.get("utc_offset", "+00:00"))
        wh = resp.get("working_hours", "09:00-17:00")
        parts = wh.split("-")
        wstart = timetominutes(parts[0])
        wend = timetominutes(parts[1])
        note = resp.get("note", "").lower()
        busy = []
        for ev in eventsfromresponse(resp):
            if ev.get("show_as") == "busy":
                bs = timetominutes(ev.get("start"))
                be = timetominutes(ev.get("end"))
                if "between any meeting with me" in note:
                    bs -= 15
                    be += 15
                busy.append((bs, be))
        nowednesday = "no-meeting wednesdays" in note and daykey == "wed"
        startbound = -1
        if "before 10:00" in note:
            startbound = 10 * 60
        lunchblock = "lunch" in note and "12:00" in note and "13:00" in note
        offlineblock = "offline from 15:30" in note and (daykey == "tue" or daykey == "thu")
        return {
            "offset": off,
            "work_start": wstart,
            "work_end": wend,
            "busy": busy,
            "no_wednesday": nowednesday,
            "start_bound": startbound,
            "lunch_block": lunchblock,
            "offline_block": offlineblock,
        }

    def isfree(startm, endm, info, daykey):
        localstart = startm + info["offset"]
        localend = endm + info["offset"]

        if info["no_wednesday"]:
            return False
        if localstart < info["work_start"] or localend > info["work_end"]:
            return False
        if info["start_bound"] != -1 and localstart < info["start_bound"]:
            return False
        if info["lunch_block"]:
            if overlap(localstart, localend, 12 * 60, 13 * 60):
                return False
        if info["offline_block"]:
            if localend > 15 * 60 + 30:
                return False

        for bs, be in info["busy"]:
            if overlap(localstart, localend, bs, be):
                return False
        return True

    uniqueattendees = []
    seenattendees = set()
    for person in attendees:
        if person not in seenattendees:
            seenattendees.add(person)
            uniqueattendees.append(person)

    uniquedays = []
    seendays = set()
    for day in days:
        key = normday(day)
        if key not in seendays:
            seendays.add(key)
            uniquedays.append((key, day.strip()))

    startsbyday = {}
    for daykey, rawday in uniquedays:
        userresp = api.read_calendar("", rawday)
        userwork = userresp.get("working_hours", "09:00-17:00").split("-")
        userstart = timetominutes(userwork[0])
        userend = timetominutes(userwork[1])
        if earliest != "":
            userstart = max(userstart, timetominutes(earliest))
        if latest_end != "":
            userend = min(userend, timetominutes(latest_end))
        userlateststart = userend - minutes
        if userlateststart < userstart:
            continue

        ubusy = userbusy(userresp)

        infos = []
        for person in uniqueattendees:
            presp = api.read_calendar(person, rawday)
            infos.append(personinfo(presp, daykey))

        daystarts = []
        cand = ceilquarter(userstart)
        while cand <= userlateststart:
            endm = cand + minutes
            ok = True

            for bs, be in ubusy:
                if overlap(cand, endm, bs, be):
                    ok = False
                    break

            if ok:
                for info in infos:
                    if not isfree(cand, endm, info, daykey):
                        ok = False
                        break

            if ok:
                daystarts.append(minutestotime(cand))

            cand += 15

        if len(daystarts) > 0:
            startsbyday[daykey] = daystarts

    return {"starts": startsbyday}
