        hour = total // 60
        minute = total % 60
        if hour < 10:
            hs = "0" + str(hour)
        else:
            hs = str(hour)
        if minute < 10:
            ms = "0" + str(minute)
        else:
            ms = str(minute)
        return hs + ":" + ms

    def parse_offset(text):
        if not text:
            return 0
        sign = 1
        if text[0] == "-":
            sign = -1
            text = text[1:]
        elif text[0] == "+":
            text = text[1:]
        parts = text.split(":")
        return sign * (int(parts[0]) * 60 + int(parts[1]))

    def window_segments(start, end):
        if start == end:
            return []
        if end <= 0 or start >= 1440:
            return []
        if start > end:
            pieces = []
            pieces.extend(window_segments(start, 1440))
            pieces.extend(window_segments(0, end))
            return pieces
        if start < 0:
            start = 0
        if end > 1440:
            end = 1440
        if start < end:
            return [(start, end)]
        return []

    def build_day_map(data):
        result = {}
        for item in data.get("days", []):
            result[item.get("day", "")] = item
        return result

    user_data = api.read_calendar("", "")
    user_offset = parse_offset(user_data.get("utc_offset", "+00:00"))
