            for word in words:
                if word.isdigit():
                    buffer = int(word)
                    break

        no_wed = "no meeting wednesdays" in clean_note

        day_map = build_day_map(data)
        day_info = {}

        work_parts = data.get("working_hours", "00:00-00:00").split("-")
        local_work_start = parse_time(work_parts[0])
        local_work_end = parse_time(work_parts[1])

        for day in days:
            if no_wed and day == "wed":
                day_info[day] = {"work": [], "busy": [(0, 1440)]}
            else:
                work = window_segments(local_work_start + shift, local_work_end + shift)
                busy = []
                entry = day_map.get(day, {})
                for event in entry.get("events", []):
                    if event.get("show_as", "").lower() == "busy":
                        start = parse_time(event.get("start", "00:00")) + shift - buffer
                        end = parse_time(event.get("end", "00:00")) + shift + buffer
                        busy.extend(window_segments(start, end))
                day_info[day] = {"work": work, "busy": busy}

        people_days.append(day_info)

    earliest_minutes = user_work_start
    if earliest != "":
        earliest_minutes = max(earliest_minutes, parse_time(earliest))
    earliest_minutes = ((earliest_minutes + 14) // 15) * 15

    latest_minutes = user_work_end - minutes
    if latest_end != "":
        latest_minutes = min(latest_minutes, parse_time(latest_end) - minutes)

    starts = {}
    if latest_minutes >= earliest_minutes:
        for day in days:
            day_starts = []
            start = earliest_minutes
            while start <= latest_minutes:
                end = start + minutes
                ok = True
                for person in people_days:
                    info = person.get(day, {"work": [], "busy": []})

                    work_ok = False
                    for a, b in info["work"]:
                        if start >= a and end <= b:
                            work_ok = True
                            break
                    if not work_ok:
                        ok = False
                        break

                    for a, b in info["busy"]:
                        if start < b and end > a:
                            ok = False
                            break
                    if not ok:
                        break

                if ok:
                    day_starts.append(format_time(start))
                start += 15

            if day_starts:
                starts[day] = day_starts

    return {"starts": starts}
