def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def to_minutes(text):
        parts = text.split(":")
        return int(parts[0]) * 60 + int(parts[1])

    def to_time(value):
        hour = value // 60
        minute = value % 60
        if hour < 10:
            hour_text = "0" + str(hour)
        else:
            hour_text = str(hour)
        if minute < 10:
            minute_text = "0" + str(minute)
        else:
            minute_text = str(minute)
        return hour_text + ":" + minute_text

    def round_up_quarter(value):
        rem = value % 15
        if rem == 0:
            return value
        return value + (15 - rem)

    def first_time(text, start):
        i = start
        limit = len(text) - 4
        while i <= limit:
            if (text[i].isdigit() and text[i + 1].isdigit() and text[i + 2] == ":" and
                    text[i + 3].isdigit() and text[i + 4].isdigit()):
                return to_minutes(text[i:i + 5])
            i += 1
        return None

    def day_match(text, day):
        if day == "mon":
            return "mon" in text or "monday" in text
        if day == "tue":
