        work_low = to_minutes(work_parts[0])
        work_high = to_minutes(work_parts[1])
        note = calendar.get("note", "")
        note = note.lower()
        for entry in calendar.get("days", []):
            day = entry.get("day", "")
            low = work_low
            high = work_high

            if "before" in note and ("book" in note or "don't" in note or "do not" in note):
                pos = note.find("before")
                t = first_time(note, pos)
                if t is not None and t > low:
                    low = t

            if "offline from" in note and day_match(note, day):
                pos = note.find("offline from")
                t = first_time(note, pos)
                if t is not None and t < high:
                    high = t

            busy = []
            for event in entry.get("events", []):
                if event.get("show_as", "busy") != "free":
                    start = to_minutes(event["start"])
                    end = to_minutes(event["end"])
                    busy.append((start, end))
            info[day] = (low, high, busy)
        return info

    people = [""]
    for person in attendees:
