    calendars = {}
    for person in people:
        calendars[person] = person_day_info(api.read_calendar(person, ""))

    result = {}
    earliest_min = 0
    if earliest != "":
        earliest_min = to_minutes(earliest)
    latest_min = 24 * 60
    if latest_end != "":
        latest_min = to_minutes(latest_end)

    for day in days:
        ok_day = True
        day_low = earliest_min
        day_high = latest_min

        for person in people:
            person_days = calendars.get(person, {})
            if day not in person_days:
                ok_day = False
                break
            low, high, busy = person_days[day]
            if low > day_low:
                day_low = low
            if high < day_high:
                day_high = high

        if not ok_day:
            continue

        start = round_up_quarter(day_low)
        limit = day_high - minutes
        if start > limit:
            continue

        starts = []
        t = start
        while t <= limit:
            fits = True
            end = t + minutes
            for person in people:
                low, high, busy = calendars[person][day]
                if t < low or end > high:
                    fits = False
                    break
                for busy_start, busy_end in busy:
                    if t < busy_end and end > busy_start:
                        fits = False
                        break
                if not fits:
                    break
            if fits:
                starts.append(to_time(t))
            t += 15

        if starts:
            result[day] = starts

    return {"starts": result}
