            working_hours_text = root.get("working_hours", "")

        note = ""
        if isinstance(item, dict) and "note" in item:
            note = item.get("note", "")
        elif isinstance(root, dict):
            note = root.get("note", "")

        events = []
        if isinstance(item, dict) and "events" in item and isinstance(item["events"], list):
            events = item["events"]
        elif isinstance(root, dict) and "events" in root and isinstance(root["events"], list):
            events = root["events"]

        blocks = note_blocks(note, day_key, shift)
        for event in events:
            if isinstance(event, dict):
                show_as = event.get("show_as", "busy")
                if show_as != "free":
                    start_text = event.get("start", "")
                    end_text = event.get("end", "")
                    if start_text and end_text:
                        blocks.append((parse_time(start_text) + shift, parse_time(end_text) + shift))
        work_start, work_end = parse_working_hours(working_hours_text)
        work_start += shift
        work_end += shift
        return work_start, work_end, blocks

    requested_days = []
    seen_days = set()
    for day in days:
        key = normalize_day(day)
        if key in ("mon", "tue", "wed", "thu", "fri") and key not in seen_days:
            seen_days.add(key)
            requested_days.append(key)

    if not requested_days:
        return {"starts": {}}

    people = [""]
    seen_people = set([""])
    for person in attendees:
        if person not in seen_people:
            seen_people.add(person)
            people.append(person)

    calendars = {}
    for person in people:
        calendars[person] = {}
        for day_key in requested_days:
            calendars[person][day_key] = api.read_calendar(person, day_key)

    user_offset = find_offset(calendars[""][requested_days[0]])
    if user_offset is None:
        user_offset = 0

    offsets = {}
    for person in people:
        person_offset = find_offset(calendars[person][requested_days[0]])
        if person_offset is None:
            person_offset = 0
        offsets[person] = user_offset - person_offset

    result = {}
    for day_key in requested_days:
        start_bound = 0
        end_bound = 24 * 60
        busy = []

        for person in people:
            shift = offsets[person]
            work_start, work_end, intervals = intervals_for_day(calendars[person][day_key], day_key, shift)

            if work_start > start_bound:
                start_bound = work_start
            if work_end < end_bound:
                end_bound = work_end

            for interval in intervals:
                busy.append(interval)

        if earliest:
            e = parse_time(earliest)
            if e > start_bound:
                start_bound = e

        if latest_end:
            l = parse_time(latest_end)
            if l < end_bound:
                end_bound = l

        if start_bound < 0:
            start_bound = 0
        if end_bound > 24 * 60:
            end_bound = 24 * 60

        latest_start = end_bound - minutes
        first_start = ceil_quarter(start_bound)
        starts = []

        if first_start <= latest_start:
            cand = first_start
            while cand <= latest_start:
                end_cand = cand + minutes
                if end_cand <= end_bound:
                    ok = True
                    for a, b in busy:
                        if cand < b and end_cand > a:
                            ok = False
                            break
                    if ok:
                        starts.append(format_time(cand))
                cand += 15

        if starts:
            result[day_key] = starts

    return {"starts": result}
