def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def parse_time(text):
        if not isinstance(text, str):
            text = str(text)
        s = text.strip().lower()
        if s == "noon":
            return 12 * 60
        if s == "midnight":
            return 0
        mer = 0
        if s.endswith("am") or s.endswith("pm"):
            mer = 1 if s.endswith("am") else 2
            s = s[:-2].strip()
        if ":" in s:
            parts = s.split(":")
            if len(parts) < 2:
                return -1
            if not parts[0].isdigit() or not parts[1][:2].isdigit():
                return -1
            hour = int(parts[0])
            minute = int(parts[1][:2])
        elif s.isdigit():
            hour = int(s)
            minute = 0
        else:
            return -1
        if mer == 1:
            if hour == 12:
                hour = 0
        elif mer == 2:
            if hour < 12:
                hour += 12
        if 0 <= hour < 24 and 0 <= minute < 60:
            return hour * 60 + minute
        return -1

    def parse_offset(text):
        if not isinstance(text, str):
            text = str(text)
        s = text.strip()
        if not s:
            return 0
        sign = 1
        if s[:1] == "-":
            sign = -1
        if s[:1] in "+-":
            s = s[1:]
        parts = s.split(":")
        if len(parts) == 2 and parts[0].isdigit() and parts[1][:2].isdigit():
            return sign * (int(parts[0]) * 60 + int(parts[1][:2]))
        if s.isdigit():
            return sign * (int(s) * 60)
        return 0

    def ceil_quarter(value):
        rem = value % 15
        if rem == 0:
            return value
        return value + (15 - rem)

    def merge_intervals(intervals):
        items = []
        for start, end in sorted(intervals):
            if end <= start:
                continue
            if not items:
                items.append([start, end])
            else:
                last = items[-1]
                if start <= last[1]:
                    if end > last[1]:
                        last[1] = end
                else:
                    items.append([start, end])
        return [(start, end) for start, end in items]

    def normalize(text):
        s = str(text).lower()
        chars = ["\n", "\t", ",", ";", "(", ")", "[", "]", "{", "}", "/", "\\", "|", ".", "?", "!", "–", "—"]
        for ch in chars:
            s = s.replace(ch, " ")
        s = s.replace("-", " - ")
        return s

    def tokenize(text):
        return normalize(text).split()

    def has_token(tokens, word):
        return word in tokens

    def has_phrase(text, phrase):
        return text.find(phrase) != -1

    def day_index(day):
        if day == "mon":
            return 0
        if day == "tue":
            return 1
        if day == "wed":
            return 2
        if day == "thu":
            return 3
        if day == "fri":
            return 4
        return -1

    def day_words(day):
        if day == "mon":
            return ["mon", "monday"]
        if day == "tue":
            return ["tue", "tues", "tuesday"]
        if day == "wed":
            return ["wed", "wednesday"]
        if day == "thu":
            return ["thu", "thur", "thurs", "thursday"]
        if day == "fri":
            return ["fri", "friday"]
        return []

    def applies_to_day(text, day):
        tokens = tokenize(text)
        words = day_words(day)
        found = []
        for i, token in enumerate(tokens):
            if token in ["mon", "monday", "tue", "tues", "tuesday", "wed", "wednesday", "thu", "thur", "thurs", "thursday", "fri", "friday"]:
                found.append((i, token))
        if not found:
            return True
        if any(token in words for _, token in found):
            return True
        target = day_index(day)
        if target < 0:
            return False
        for a in range(len(found)):
            for b in range(a + 1, len(found)):
                i1, t1 = found[a]
                i2, t2 = found[b]
                if i2 <= i1:
                    continue
                between = tokens[i1 + 1:i2]
                if any(x in ["-", "to", "through", "thru", "until", "till", "til"] for x in between):
                    if day_index(t1[:3]) <= target <= day_index(t2[:3]):
                        return True
        return False

    def parseFreeTimeItem(tokens, i):
        token = tokens[i]
        prev = tokens[i - 1] if i > 0 else ""
        nxt = tokens[i + 1] if i + 1 < len(tokens) else ""
        if token == "noon":
            return 720, 12, 0, 1, 1
        if token == "midnight":
            return 0, 0, 0, 0, 1

        mer = 0
        base = token
        span = 1

        if base.endswith("am") or base.endswith("pm"):
            mer = 1 if base.endswith("am") else 2
            base = base[:-2]
        elif nxt in ["am", "pm"] and (base.isdigit() or ":" in base):
            mer = 1 if nxt == "am" else 2
            span = 2

        if ":" in base:
            parts = base.split(":")
            if len(parts) < 2:
                return -1, -1, -1, 0, 1
            if not parts[0].isdigit() or len(parts[1]) < 2 or not parts[1][:2].isdigit():
                return -1, -1, -1, 0, 1
            hour = int(parts[0])
            minute = int(parts[1][:2])
        elif base.isdigit():
            if not (prev in ["at", "from", "after", "since", "before", "until", "till", "between", "around", "by", "-", "lunch", "focus", "break", "call", "review", "doctor", "travel", "flight", "class", "school", "training", "interview", "appointment", "hold", "busy", "sync", "standup", "meeting", "offsite", "vacation", "pto", "ooo", "reserved", "conflict", "private", "available"] or nxt in ["am", "pm", "-", "to"]):
                return -1, -1, -1, 0, 1
            hour = int(base)
            minute = 0
        else:
            return -1, -1, -1, 0, 1

        raw_hour = hour
        if mer == 1:
            if hour == 12:
                hour = 0
        elif mer == 2:
            if hour < 12:
                hour += 12

        if 0 <= hour < 24 and 0 <= minute < 60:
            return hour * 60 + minute, raw_hour, minute, mer, span
        return -1, -1, -1, 0, 1

    def convert_with_meridiem(hour, minute, mer):
        if mer == 1:
            if hour == 12:
                hour = 0
        elif mer == 2:
            if hour < 12:
                hour += 12
        return hour * 60 + minute

    def add_interval(items, start, end):
        if end <= start:
            if end > 0:
                if start < 0:
                    start = 0
                if end > 1440:
                    end = 1440
                if start < 1440:
                    items.append((start, 1440))
                if end > 0:
                    items.append((0, end))
            return
        if start < 0:
            start = 0
        if end > 1440:
            end = 1440
        if end > start:
            items.append((start, end))

    def extract_intervals(text, day):
        if not text:
            return []
        if not applies_to_day(text, day):
            return []
        tokens = tokenize(text)
        items = []
        for i in range(len(tokens)):
            mins, raw_hour, minute, mer, span = parseFreeTimeItem(tokens, i)
            if mins >= 0:
                items.append((i, mins, raw_hour, minute, mer, span))

        intervals = []
        for i in range(len(items)):
            pos, mins, raw_hour, minute, mer, span = items[i]
            prev = tokens[pos - 1] if pos > 0 else ""
            if prev in ["after", "since", "from"]:
                add_interval(intervals, mins, 24 * 60)
            if prev in ["before", "until", "till", "til"]:
                add_interval(intervals, 0, mins)

        for i in range(len(items) - 1):
            p1 = items[i]
            p2 = items[i + 1]
            end1 = p1[0] + p1[5]
            between = tokens[end1:p2[0]]
            if not between:
                continue
            if any(x in ["-", "to", "through", "thru", "until", "till", "til"] for x in between):
                start_min = p1[1]
                end_min = p2[1]
                start_raw = p1[2]
                start_minute = p1[3]
                start_mer = p1[4]
                end_raw = p2[2]
                end_minute = p2[3]
                end_mer = p2[4]
                if start_mer == 0 and end_mer != 0:
                    if end_mer == 2:
                        if start_raw <= end_raw:
                            start_min = convert_with_meridiem(start_raw, start_minute, 2)
                        else:
                            start_min = convert_with_meridiem(start_raw, start_minute, 1)
                    else:
                        if start_raw <= end_raw:
                            start_min = convert_with_meridiem(start_raw, start_minute, 1)
                        else:
                            start_min = convert_with_meridiem(start_raw, start_minute, 2)
                elif start_mer != 0 and end_mer == 0:
                    if start_mer == 2:
                        if end_raw >= start_raw:
                            end_min = convert_with_meridiem(end_raw, end_minute, 2)
                        else:
                            end_min = convert_with_meridiem(end_raw, end_minute, 1)
                    else:
                        if end_raw >= start_raw:
                            end_min = convert_with_meridiem(end_raw, end_minute, 1)
                        else:
                            end_min = convert_with_meridiem(end_raw, end_minute, 2)
                if end_min <= start_min:
                    if end_min > 0:
                        add_interval(intervals, start_min, 24 * 60)
                        add_interval(intervals, 0, end_min)
                else:
                    add_interval(intervals, start_min, end_min)

        return merge_intervals(intervals)

    def is_event_blocking_text(text):
        if not text:
            return False
        lower = str(text).lower()
        tokens = tokenize(lower)
        negative_words = [
            "busy", "lunch", "focus", "break", "call", "appointment", "hold", "blocked",
            "private", "doctor", "travel", "flight", "commute", "class", "school",
            "training", "review", "interview", "vacation", "pto", "ooo", "offsite",
            "unavailable", "away", "reserved", "conflict", "sync", "standup", "1:1"
        ]
        negative_phrases = [
            "out of office", "out of town", "do not schedule", "do not book",
            "focus time", "working lunch", "day off", "one on one", "no meeting", "no meetings"
        ]
        if any(has_token(tokens, w) for w in negative_words):
            return True
        if any(has_phrase(lower, p) for p in negative_phrases):
            return True
        return False

    def note_blocks(text, day):
        if not text:
            return []
        lower = str(text).lower()
        if not applies_to_day(lower, day):
            return []
        tokens = tokenize(lower)
        positive = any(has_token(tokens, w) for w in ["free", "available", "open", "flexible"])
        negative_words = [
            "busy", "lunch", "focus", "break", "call", "appointment", "hold", "blocked",
            "private", "doctor", "travel", "flight", "commute", "class", "school",
            "training", "review", "interview", "vacation", "pto", "ooo", "offsite",
            "unavailable", "away", "reserved", "conflict", "sync", "standup", "meeting", "1:1"
        ]
        negative_phrases = [
            "out of office", "out of town", "do not schedule", "do not book",
            "focus time", "working lunch", "day off", "one on one", "no meeting", "no meetings"
        ]
        negative = any(has_token(tokens, w) for w in negative_words) or any(has_phrase(lower, p) for p in negative_phrases)
        if positive and not negative:
            return []

        intervals = extract_intervals(lower, day)
        if intervals:
            return intervals

        time_items = []
        for i in range(len(tokens)):
            mins, raw_hour, minute, mer, span = parseFreeTimeItem(tokens, i)
            if mins >= 0:
                time_items.append((mins, raw_hour, minute, mer, span))

        if positive:
            return []

        if len(time_items) == 1:
            s = time_items[0][0]
            add = [(s, s + 60)]
            return merge_intervals(add)

        if has_token(tokens, "morning"):
            return [(0, 12 * 60)]
        if has_token(tokens, "afternoon"):
            return [(12 * 60, 24 * 60)]
        if has_token(tokens, "evening"):
            return [(17 * 60, 24 * 60)]

        if negative:
            return [(0, 24 * 60)]
        return []

    def day_record(data, day):
        if not isinstance(data, dict):
            return {}
        if "days" in data and isinstance(data.get("days"), list):
            for item in data.get("days", []):
                if isinstance(item, dict):
                    if item.get("day", "") == day or item.get("key", "") == day:
                        return item
            if len(data.get("days", [])) == 1 and isinstance(data.get("days", [])[0], dict):
                return data.get("days", [])[0]
        return data

    def field_value(data, record, key, default):
        if isinstance(record, dict) and key in record:
            return record.get(key, default)
        if isinstance(data, dict) and key in data:
            return data.get(key, default)
        return default

    def parse_hours(text):
        s = str(text) if text is not None else ""
        parts = s.split("-", 1)
        if len(parts) != 2:
            return 9 * 60, 17 * 60
        start = parse_time(parts[0])
        end = parse_time(parts[1])
        if start < 0 or end < 0:
            return 9 * 60, 17 * 60
        return start, end

    def busy_intervals(data, record, day):
        items = []
        events = field_value(data, record, "events", [])
        if not isinstance(events, list):
            events = []
        for event in events:
            if not isinstance(event, dict):
                continue
            start = parse_time(event.get("start", ""))
            end = parse_time(event.get("end", ""))
            if start < 0 or end < 0:
                continue
            show = str(event.get("show_as", "busy")).lower()
            text_parts = []
            for key in event:
                if key in ["start", "end", "show_as"]:
                    continue
                value = event.get(key)
                if isinstance(value, str):
                    text_parts.append(value)
            text = " ".join(text_parts)
            if show != "free" or is_event_blocking_text(text):
                add_interval(items, start, end)

        note = field_value(data, record, "note", "")
        for start, end in note_blocks(note, day):
            add_interval(items, start, end)

        return merge_intervals(items)

    def free_at(calendar, user_start, user_end, user_offset):
        delta = calendar["offset"] - user_offset
        local_start = user_start + delta
        local_end = user_end + delta
        if local_start < 0 or local_end > 24 * 60:
            return False
        if local_start < calendar["work_start"] or local_end > calendar["work_end"]:
            return False
        for start, end in calendar["busy"]:
            if local_start < end and local_end > start:
                return False
        return True

    cache = {}
    result = {}

    for day in days:
        calendars = []
        people = [""] + [person for person in attendees]
        for person in people:
            key = (person, day)
            if key not in cache:
                try:
                    cache[key] = api.read_calendar(person, day)
                except Exception:
                    cache[key] = {}
            data = cache[key]
            record = day_record(data, day)
            offset_text = field_value(data, record, "utc_offset", "+00:00")
            working_text = field_value(data, record, "working_hours", "09:00-17:00")
            calendars.append({
                "offset": parse_offset(offset_text),
                "work_start": parse_hours(working_text)[0],
                "work_end": parse_hours(working_text)[1],
                "busy": busy_intervals(data, record, day),
            })

        user_calendar = calendars[0]
        user_offset = user_calendar["offset"]

        start_bound = user_calendar["work_start"]
        if earliest:
            t = parse_time(earliest)
            if t >= 0 and t > start_bound:
                start_bound = t

        end_bound = user_calendar["work_end"] - minutes
        if latest_end:
            t = parse_time(latest_end)
            if t >= 0:
                candidate = t - minutes
                if candidate < end_bound:
                    end_bound = candidate

        start_bound = ceil_quarter(start_bound)
        starts = []

        if start_bound <= end_bound:
            for start in range(start_bound, end_bound + 1, 15):
                end = start + minutes
                if end > user_calendar["work_end"]:
                    continue
                ok = True
                for calendar in calendars:
                    if not free_at(calendar, start, end, user_offset):
                        ok = False
                        break
                if ok:
                    starts.append(str(start // 60).zfill(2) + ":" + str(start % 60).zfill(2))

        if starts:
            result[day] = starts

    return {"starts": result}
