def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def parseSimpleTime(text):
        s = str(text).strip().lower()
        if s == "":
            return None
        s = s.replace(" ", "")
        pos = -1
        for i in range(len(s)):
            if s[i].isdigit():
                pos = i
                break
        if pos == -1:
            return None
        s = s[pos:]
        ampm = ""
        if s.endswith("am") or s.endswith("pm"):
            ampm = s[-2:]
            s = s[:-2]
        hour = 0
        minute = 0
        try:
            if ":" in s:
                parts = s.split(":")
                hour = int(parts[0])
                minuteText = parts[1]
                digits = ""
                for ch in minuteText:
                    if ch.isdigit():
                        digits += ch
                    else:
                        break
                if digits != "":
                    minute = int(digits[:2])
            else:
                digits = ""
                for ch in s:
                    if ch.isdigit():
                        digits += ch
                    else:
                        break
                if digits == "":
                    return None
                hour = int(digits)
        except Exception:
            return None
        if ampm == "pm" and hour < 12:
            hour += 12
        if ampm == "am" and hour == 12:
            hour = 0
        if hour == 24 and minute == 0:
            return 1440
        if hour < 0 or hour > 24 or minute < 0 or minute >= 60:
            return None
        return hour * 60 + minute

    def parseAnyTime(text):
        s = str(text).strip()
        if s == "":
            return None
        if "T" in s:
            s = s.split("T")[-1]
        elif len(s) > 8 and s[:4].isdigit() and ("-" in s or " " in s):
            if " " in s:
                s = s.split(" ")[-1]
        s = s.replace(" ", "")
        if "Z" in s:
            s = s.split("Z")[0]
        if "+" in s:
            s = s.split("+")[0]
        if "-" in s and s.count(":") >= 1 and s[:1].isdigit():
            s = s.split("-")[0]
        return parseSimpleTime(s)

    def formatTime(value):
        h, m = divmod(value, 60)
        return str(h).zfill(2) + ":" + str(m).zfill(2)

    def parseOffset(text):
        if isinstance(text, int):
            return text
        s = str(text).strip().upper()
        if s == "" or s == "Z" or s == "UTC" or s == "GMT":
            return 0
        sign = 1
        pos = -1
        for i in range(len(s)):
            if s[i] == "+":
                sign = 1
                pos = i
                break
            if s[i] == "-":
                sign = -1
                pos = i
                break
        if pos == -1:
            return 0
        rest = s[pos + 1:]
        if rest.startswith("UTC"):
            rest = rest[3:]
        if rest.startswith("GMT"):
            rest = rest[3:]
        rest = rest.strip()
        if rest == "":
            return 0
        digits = ""
        for ch in rest:
            if ch.isdigit():
                digits += ch
            else:
                break
        if digits == "":
            return 0
        hours = 0
        mins = 0
        try:
            if ":" in rest:
                parts = rest.split(":")
                hours = int(parts[0])
                minuteDigits = ""
                for ch in parts[1]:
                    if ch.isdigit():
                        minuteDigits += ch
                    else:
                        break
                if minuteDigits != "":
                    mins = int(minuteDigits[:2])
            elif len(digits) <= 2:
                hours = int(digits)
                mins = 0
            else:
                hours = int(digits[:-2])
                mins = int(digits[-2:])
        except Exception:
            return 0
        return sign * (hours * 60 + mins)

    def ceilQuarter(value):
        rem = value % 15
        if rem == 0:
            return value
        return value + (15 - rem)

    def mergeIntervals(intervals):
        items = []
        for item in sorted(intervals):
            if len(item) < 2:
                continue
            start = item[0]
            end = item[1]
            if start is None or end is None:
                continue
            if end <= start:
                continue
            if end <= 0 or start >= 24 * 60:
                continue
            if start < 0:
