            piece = part.strip()
            if piece != "":
                pieces.append(piece)
        return pieces

    def parseSimpleTime(text):
        s = str(text).strip().lower()
        if s == "":
            return None
        s = s.replace(" ", "")
        pos = -1
        for i in range(len(s)):
            if s[i].isdigit():
                pos = i
                break
        if pos == -1:
            return None
        s = s[pos:]
        ampm = ""
        if s.endswith("am") or s.endswith("pm"):
            ampm = s[-2:]
            s = s[:-2]
        hour = 0
        minute = 0
        try:
            if ":" in s:
                parts = s.split(":")
                hour = int(parts[0])
                minuteText = parts[1]
                digits = ""
                for ch in minuteText:
                    if ch.isdigit():
                        digits += ch
                    else:
                        break
                if digits != "":
                    minute = int(digits[:2])
            else:
                digits = ""
                for ch in s:
                    if ch.isdigit():
                        digits += ch
                    else:
                        break
                if digits == "":
                    return None
                if len(digits) == 3:
                    hour = int(digits[:1])
                    minute = int(digits[1:])
                elif len(digits) >= 4:
                    hour = int(digits[:-2])
                    minute = int(digits[-2:])
                else:
                    hour = int(digits)
        except Exception:
            return None
        if ampm == "pm" and hour < 12:
            hour += 12
        if ampm == "am" and hour == 12:
            hour = 0
        if hour == 24 and minute == 0:
            return 24 * 60
        if hour < 0 or hour > 24 or minute < 0 or minute >= 60:
            return None
        return hour * 60 + minute

    def parseAnyTime(text):
        s = str(text).strip()
        if s == "":
            return None
        if "T" in s:
            s = s.split("T")[-1]
        if " " in s:
            parts = s.split()
            if len(parts) > 0:
                maybe = parts[-1]
                if parseSimpleTime(maybe) is not None:
                    s = maybe
                else:
                    s = parts[0]
        if s.endswith("Z"):
            s = s[:-1]
        if "+" in s:
            s = s.split("+")[0]
        if "-" in s:
            pos = -1
            for i in range(len(s)):
                if s[i] == "-":
                    pos = i
            if pos > 0 and ":" in s and pos > s.find(":"):
                s = s[:pos]
        return parseSimpleTime(s)

    def formatTime(value):
        h, m = divmod(value, 60)
        return str(h).zfill(2) + ":" + str(m).zfill(2)

    def parseOffset(text):
        if isinstance(text, int):
            return text
        s = str(text).strip().upper()
        if s == "" or s == "Z" or s == "UTC" or s == "GMT":
            return 0
        sign = 1
        pos = -1
        for i in range(len(s)):
            if s[i] == "+":
                sign = 1
                pos = i
                break
            if s[i] == "-":
                sign = -1
                pos = i
                break
        if pos == -1:
            return 0
        rest = s[pos + 1:]
        if rest.startswith("UTC"):
            rest = rest[3:]
        if rest.startswith("GMT"):
            rest = rest[3:]
        rest = rest.strip()
        if rest == "":
            return 0
        digits = ""
        for ch in rest:
            if ch.isdigit():
                digits += ch
            else:
                break
        if digits == "":
            return 0
        hours = 0
        mins = 0
        try:
            if ":" in rest:
                parts = rest.split(":")
                hours = int(parts[0])
                minuteDigits = ""
                for ch in parts[1]:
                    if ch.isdigit():
                        minuteDigits += ch
                    else:
                        break
                if minuteDigits != "":
                    mins = int(minuteDigits[:2])
            elif len(digits) <= 2:
                hours = int(digits)
                mins = 0
            else:
                hours = int(digits[:-2])
                mins = int(digits[-2:])
        except Exception:
            return 0
        return sign * (hours * 60 + mins)

    def ceilQuarter(value):
        rem = value % 15
        if rem == 0:
            return value
        return value + (15 - rem)

    def expandInterval(start, end):
        if end <= start:
            if start <= 12 * 60 and end <= 12 * 60:
                end += 12 * 60
            else:
                end += 24 * 60
        return start, end

    def dayWords(day):
        d = str(day).lower().strip()
        if d.startswith("mon"):
            return ["monday", "mondays", "mon"]
        if d.startswith("tue"):
            return ["tuesday", "tuesdays", "tue", "tues"]
        if d.startswith("wed"):
            return ["wednesday", "wednesdays", "wed"]
        if d.startswith("thu"):
            return ["thursday", "thursdays", "thu", "thur", "thurs"]
        if d.startswith("fri"):
            return ["friday", "fridays", "fri"]
        return []

    def allDayWords():
        return [
            "monday", "mondays", "mon",
            "tuesday", "tuesdays", "tue", "tues",
            "wednesday", "wednesdays", "wed",
            "thursday", "thursdays", "thu", "thur", "thurs",
            "friday", "fridays", "fri"
        ]

    def containsAny(text, words):
        for word in words:
            if word in text:
                return True
        return False

    def appliesToDay(text, day):
        raw = str(text).lower()
        low = " " + normalizeText(text) + " "

        genericWords = [
            "every weekday", "weekdays", "weekday", "business days", "business day",
            "every day", "daily", "all days",
            "monday-friday", "mon-fri", "monday to friday", "mon to fri",
            "monday through friday", "mon through fri",
            "monday thru friday", "mon thru fri"
        ]
        for phrase in genericWords:
            if phrase in raw or (" " + phrase + " ") in low:
                return True

        currentWords = dayWords(day)
        for word in currentWords:
            if word in raw or (" " + word + " ") in low:
                return True

        otherWords = allDayWords()
        for word in currentWords:
            if word in otherWords:
                otherWords.remove(word)

        for word in otherWords:
            if word in raw or (" " + word + " ") in low:
                return False

        if "weekend" in raw or "weekends" in raw or " weekend " in low or " weekends " in low:
            return False

        return True

    def timePoints(text):
        s = str(text)
        points = []

        def addPoint(value):
            if value is not None and value not in points:
                points.append(value)

        i = 0
        while i < len(s):
            if s[i] == ":":
                left = i - 1
                while left >= 0 and s[left].isdigit():
                    left -= 1
                right = i + 1
                while right < len(s) and s[right].isdigit():
                    right += 1
                hourText = s[left + 1:i]
                minuteText = s[i + 1:right]
                if len(hourText) > 0 and len(minuteText) >= 2:
                    try:
                        hour = int(hourText)
                        minute = int(minuteText[:2])
                    except Exception:
                        i += 1
                        continue
                    if minute < 60 and hour >= 0 and hour <= 24:
                        after = right
                        while after < len(s) and s[after] == " ":
                            after += 1
                        suffix = s[after:after + 2].lower()
                        if suffix == "pm" and hour < 12:
                            hour += 12
                        if suffix == "am" and hour == 12:
                            hour = 0
                        if hour == 24 and minute == 0:
                            addPoint(24 * 60)
                        else:
                            addPoint(hour * 60 + minute)
                i = right
            i += 1

        tokens = normalizeText(text).split()
        triggerWords = ["before", "after", "from", "until", "till", "by", "at", "between", "around", "about", "to", "open", "available", "free"]
        for index in range(len(tokens)):
            token = tokens[index]
            prevToken = ""
            nextToken = ""
            if index > 0:
                prevToken = tokens[index - 1]
            if index + 1 < len(tokens):
                nextToken = tokens[index + 1]

            if token == "noon":
                addPoint(12 * 60)
                continue
            if token == "midnight":
                addPoint(0)
                continue

            if "-" in token and token.count("-") == 1:
                parts = token.split("-")
                if len(parts) == 2:
                    leftPart = parts[0]
                    rightPart = parts[1]
                    leftValue = parseSimpleTime(leftPart)
                    rightValue = parseSimpleTime(rightPart)
                    if leftValue is not None and rightValue is not None:
                        addPoint(leftValue)
                        addPoint(rightValue)
                        continue

            value = parseSimpleTime(token)
            if value is None:
                continue

            if ":" in token or token.endswith("am") or token.endswith("pm"):
                addPoint(value)
                continue

            if token.isdigit():
                if prevToken in triggerWords or nextToken in ["am", "pm"]:
                    addPoint(value)
                    continue

        return points

    def parseDuration(value):
        if isinstance(value, int):
            return value
        s = normalizeText(value)
        if s == "":
            return None
        total = 0
        digits = ""
        found = False
        for ch in s:
            if ch.isdigit():
                digits += ch
            else:
                if digits != "":
                    num = int(digits)
                    found = True
                    if ch == "h":
                        total += num * 60
                    elif ch == "m":
                        total += num
                    else:
                        total += num
                    digits = ""
        if digits != "":
            total += int(digits)
            found = True
        if not found:
            return None
        return total

    def extractBufferMinutes(text):
        low = " " + normalizeText(text) + " "
        if "no buffer" in low or "without buffer" in low or "zero buffer" in low:
            return 0
        if "buffer" not in low and "padding" not in low and "gap" not in low and "transition" not in low:
            return 0
        words = low.split()
        best = 0
        for i in range(len(words)):
            if words[i] in ["buffer", "padding", "gap", "transition", "pad"]:
                start = i - 2
                if start < 0:
                    start = 0
                end = i + 3
                if end > len(words):
                    end = len(words)
                for j in range(start, end):
                    token = words[j]
                    dur = parseDuration(token)
                    if dur is not None and dur > best:
                        best = dur
                if best == 0:
                    best = 15
        return best

    def parseIntervalsFromText(text, day, mode):
        intervals = []
        pieces = textPieces(text)
        for piece in pieces:
            if not appliesToDay(piece, day):
                continue
            raw = str(piece)
            lowRaw = raw.lower()
            low = " " + normalizeText(raw) + " "
            points = timePoints(raw)

            busyWords = [
                " busy ", " hold ", " lunch ", " lunch break ", " focus ", " focus time ",
                " deep work ", " heads down ", " quiet time ", " blocked ", " blocked off ",
                " unavailable ", " not available ", " do not schedule ", " do not book ",
                " dont schedule ", " dont book ", " don t schedule ", " don t book ",
                " no meeting ", " no meetings ", " no call ", " no calls ", " out of office ",
                " ooo ", " vacation ", " pto ", " sick ", " leave ", " holiday ", " away ",
                " appointment ", " meeting ", " meetings ", " call ", " calls ", " class ",
                " interview ", " training ", " webinar ", " workshop ", " session ", " sync ",
                " break ", " personal ", " private ", " family ", " commute ", " travel ",
                " prep ", " review ", " buffer ", " admin ", " blackout ", " do not disturb ",
                " dnd ", " reserved ", " booked ", " occupied ", " protected "
            ]
            freeWords = [" free ", " available ", " open ", " transparent "]
            fullDayWords = [
                "all day", "all-day", "full day", "out of office", "ooo",
                "vacation", "pto", "sick", "leave", "holiday"
            ]

            if mode == "free":
                if not containsAny(low, freeWords):
                    continue
                if containsAny(low, [" not available ", " unavailable ", " do not schedule ", " do not book ", " dont schedule ", " dont book ", " don t schedule ", " don t book "]):
                    continue
                if len(points) >= 2:
                    i = 0
                    while i + 1 < len(points):
                        a = points[i]
                        b = points[i + 1]
                        if b <= a:
                            b += 24 * 60
                        intervals.append((a, b))
                        i += 2
                    continue
                if len(points) == 1:
                    if " after " in low or " from " in low:
                        intervals.append((points[0], 24 * 60))
                        continue
                    if " before " in low or " until " in low or " till " in low or " by " in low:
                        intervals.append((0, points[0]))
                        continue
                if containsAny(lowRaw, ["available all day", "free all day", "open all day"]):
                    intervals.append((0, 24 * 60))
                continue

            if mode == "busy":
                if containsAny(low, fullDayWords) and len(points) == 0:
                    intervals.append((0, 24 * 60))
                    continue
                if len(points) >= 2:
                    i = 0
                    while i + 1 < len(points):
                        a = points[i]
                        b = points[i + 1]
                        if b <= a:
                            b += 24 * 60
                        intervals.append((a, b))
                        i += 2
                    continue
                if len(points) == 1:
                    if " after " in low or " from " in low:
                        intervals.append((points[0], 24 * 60))
                        continue
                    if " before " in low or " until " in low or " till " in low or " by " in low:
                        intervals.append((0, points[0]))
                        continue
                    if containsAny(low, busyWords):
                        intervals.append((0, 24 * 60))
                        continue
                if len(points) == 0 and containsAny(low, busyWords):
                    intervals.append((0, 24 * 60))
                    continue

        return intervals

    def textOf(value):
        if value is None:
            return ""
        if isinstance(value, str):
            return value
        if isinstance(value, dict):
            pieces = []
            for key in value:
                piece = textOf(value.get(key))
                if piece != "":
                    pieces.append(piece)
            return " ".join(pieces)
        if isinstance(value, list) or isinstance(value, tuple) or isinstance(value, set):
            pieces = []
            for item in value:
                piece = textOf(item)
                if piece != "":
                    pieces.append(piece)
            return " ".join(pieces)
        return str(value)

    def pickValue(objs, keys, default):
        for obj in objs:
            if isinstance(obj, dict):
                for key in keys:
                    if key in obj:
                        value = obj.get(key)
                        if value is not None and value != "":
                            return value
        return default

    def getEvents(obj):
        if isinstance(obj, dict):
            for key in ["events", "calendar", "items", "appointments", "busy", "blocks", "entries"]:
                if key in obj:
                    return obj.get(key)
            for key in ["schedule", "calendars"]:
                if key in obj and isinstance(obj.get(key), dict):
                    nested = obj.get(key)
                    for inner in ["events", "items", "appointments", "busy", "blocks", "entries"]:
                        if inner in nested:
                            return nested.get(inner)
        if isinstance(obj, list) or isinstance(obj, tuple) or isinstance(obj, set):
            return obj
        return None

    def parseWorkHours(value):
        start = 9 * 60
        end = 17 * 60
        if isinstance(value, dict):
            startValue = value.get("start", value.get("from", "09:00"))
            endValue = value.get("end", value.get("to", "17:00"))
            startMaybe = parseAnyTime(startValue)
            endMaybe = parseAnyTime(endValue)
            if startMaybe is not None:
                start = startMaybe
            if endMaybe is not None:
                end = endMaybe
            start, end = expandInterval(start, end)
            return start, end
        if isinstance(value, list) or isinstance(value, tuple):
            if len(value) >= 2:
                startMaybe = parseAnyTime(value[0])
                endMaybe = parseAnyTime(value[1])
                if startMaybe is not None:
                    start = startMaybe
                if endMaybe is not None:
                    end = endMaybe
                start, end = expandInterval(start, end)
                return start, end
        text = str(value)
        points = timePoints(text)
        if len(points) >= 2:
            start = points[0]
            end = points[1]
            start, end = expandInterval(start, end)
            return start, end
        low = text.lower()
        pieces = []
        if " to " in low:
            pieces = low.split(" to ")
        elif "-" in text:
            pieces = text.split("-")
        if len(pieces) >= 2:
            startMaybe = parseAnyTime(pieces[0])
            endMaybe = parseAnyTime(pieces[1])
            if startMaybe is not None and endMaybe is not None:
                start = startMaybe
                end = endMaybe
                start, end = expandInterval(start, end)
                return start, end
        return start, end

    def mergeIntervals(intervals):
        items = []
        for item in sorted(intervals):
            if len(item) < 2:
                continue
            start = item[0]
            end = item[1]
            if start is None or end is None:
                continue
            if end <= start:
                continue
            if end <= 0 or start >= 24 * 60:
                continue
            if start < 0:
                start = 0
            if end > 24 * 60:
                end = 24 * 60
            if end <= start:
                continue
            if not items:
                items.append([start, end])
            else:
                last = items[-1]
                if start <= last[1]:
                    if end > last[1]:
                        last[1] = end
                else:
                    items.append([start, end])
        merged = []
        for start, end in items:
            merged.append((start, end))
        return merged

    def chooseData(raw, day):
        source = raw
        if isinstance(raw, dict):
            if day in raw:
                value = raw.get(day)
                if isinstance(value, dict):
                    source = value
                elif isinstance(value, list) or isinstance(value, tuple) or isinstance(value, set):
                    source = {"events": list(value)}
            if isinstance(raw.get("days", None), list):
                found = None
                for item in raw.get("days", []):
                    if isinstance(item, dict) and item.get("day", "") == day:
                        found = item
                        break
                if found is not None:
                    source = found
            if isinstance(raw.get("schedule", None), dict):
                nested = raw.get("schedule")
                if day in nested:
                    value = nested.get(day)
                    if isinstance(value, dict):
                        source = value
                    elif isinstance(value, list) or isinstance(value, tuple) or isinstance(value, set):
                        source = {"events": list(value)}
        elif isinstance(raw, list) or isinstance(raw, tuple) or isinstance(raw, set):
            source = {"events": list(raw)}
        return source

    def eventIntervals(event, day):
        busy = []
        free = []

        if isinstance(event, dict):
            if event.get("cancelled") == True or event.get("canceled") == True:
                return busy, free
            statusText = str(event.get("status", "")).lower()
            if statusText in ["cancelled", "canceled", "declined", "deleted"]:
                return busy, free

            fullText = textOf(event)
            start = None
            end = None
            for key in ["start", "begin", "from"]:
                if key in event and event.get(key) not in [None, ""]:
                    start = parseAnyTime(event.get(key))
                    if start is not None:
                        break
            for key in ["end", "finish", "to"]:
                if key in event and event.get(key) not in [None, ""]:
                    end = parseAnyTime(event.get(key))
                    if end is not None:
                        break
            if start is not None and end is None:
                duration = event.get("duration", "")
                if isinstance(duration, int):
                    end = start + duration
                else:
                    dur = parseDuration(duration)
                    if dur is not None:
                        end = start + dur
                    else:
                        dur2 = parseAnyTime(duration)
                        if dur2 is not None:
                            end = start + dur2
            if start is not None and end is not None:
                start, end = expandInterval(start, end)

            showText = str(event.get("show_as", event.get("showAs", ""))).lower()
            availText = str(event.get("availability", "")).lower()

            explicitFree = False
            if event.get("free") == True or event.get("is_free") == True:
                explicitFree = True
            if event.get("busy") == False or event.get("is_busy") == False:
                explicitFree = True
            if event.get("transparent") == True or event.get("isTransparent") == True:
                explicitFree = True
            if showText in ["free", "available", "open", "transparent"]:
                explicitFree = True
            if availText in ["free", "available", "open", "transparent"]:
                explicitFree = True
            if statusText in ["free", "available", "open"]:
                explicitFree = True

            explicitBusy = False
            if event.get("busy") == True or event.get("is_busy") == True:
                explicitBusy = True
            if showText in ["busy", "tentative", "away", "oof", "out of office", "unavailable", "blocked"]:
                explicitBusy = True
            if availText in ["busy", "tentative", "away", "oof", "out of office", "unavailable", "blocked"]:
                explicitBusy = True
            if statusText in ["busy", "tentative", "away", "oof", "out of office", "unavailable", "blocked"]:
                explicitBusy = True

            if event.get("all_day") == True or event.get("allDay") == True:
                hasTimeField = False
                for key in ["start", "end", "begin", "finish", "time", "when"]:
                    if key in event and event.get(key) not in [None, ""]:
                        hasTimeField = True
                if not hasTimeField and not explicitFree:
                    busy.append((0, 24 * 60))

            if start is not None and end is not None:
                if explicitFree and not explicitBusy:
                    free.append((start, end))
                else:
                    busy.append((start, end))

            if not explicitFree:
                busy.extend(parseIntervalsFromText(fullText, day, "busy"))
            free.extend(parseIntervalsFromText(fullText, day, "free"))

            if explicitBusy and len(busy) == 0 and len(free) == 0:
                busy.append((0, 24 * 60))

            return busy, free

        fullText = textOf(event)
        busy.extend(parseIntervalsFromText(fullText, day, "busy"))
        free.extend(parseIntervalsFromText(fullText, day, "free"))
        return busy, free

    def loadDay(person, day):
        raw = api.read_calendar(person, day)
        source = chooseData(raw, day)
        offsetValue = pickValue([source, raw], ["utc_offset", "utcOffset", "offset", "time_zone", "timeZone", "timezone"], "+00:00")
        workValue = pickValue([source, raw], ["working_hours", "workingHours", "hours"], "09:00-17:00")

        noteKeys = [
            "note", "notes", "remark", "remarks", "comment", "comments", "memo",
            "message", "description", "details", "info", "constraints", "constraint",
            "blackout", "blackouts", "blackout_rules", "blackoutRules", "rules",
            "rule", "instructions", "instruction", "guidelines", "guideline",
            "preferences", "preference", "policy", "policies", "availability_notes",
            "availabilityNotes", "schedule_notes", "scheduleNotes", "do_not_schedule",
            "doNotSchedule", "blocked_times", "blockedTimes", "title", "summary",
            "subject", "headline", "label", "name"
        ]

        notePieces = []
        for obj in [raw, source]:
            if isinstance(obj, dict):
                for key in noteKeys:
                    if key in obj:
                        piece = textOf(obj.get(key))
                        if piece != "":
                            notePieces.append(piece)
            elif isinstance(obj, str):
                if obj != "":
                    notePieces.append(obj)

        noteText = " ".join(notePieces)
        eventsValue = getEvents(source)
        if eventsValue is None:
            eventsValue = getEvents(raw)

        events = []
        if isinstance(eventsValue, dict):
            events = [eventsValue]
        elif isinstance(eventsValue, list) or isinstance(eventsValue, tuple) or isinstance(eventsValue, set):
            events = list(eventsValue)

        workStart, workEnd = parseWorkHours(workValue)
        if workEnd <= workStart:
            workEnd += 24 * 60

        busy = []
        free = []
        bufferMinutes = extractBufferMinutes(noteText)

        bufferKeys = ["buffer", "buffer_minutes", "bufferMinutes", "padding", "padding_minutes", "gap", "transition"]
        for obj in [raw, source]:
            if isinstance(obj, dict):
                for key in bufferKeys:
                    if key in obj:
                        value = obj.get(key)
                        if isinstance(value, int):
                            if value > bufferMinutes:
                                bufferMinutes = value
                        else:
                            dur = parseDuration(value)
                            if dur is not None and dur > bufferMinutes:
                                bufferMinutes = dur

        busy.extend(parseIntervalsFromText(noteText, day, "busy"))
        free.extend(parseIntervalsFromText(noteText, day, "free"))

        for event in events:
            eventBusy, eventFree = eventIntervals(event, day)
            busy.extend(eventBusy)
            free.extend(eventFree)

        if bufferMinutes > 0:
            paddedBusy = []
            for start, end in busy:
                a = start - bufferMinutes
                b = end + bufferMinutes
                if a < 0:
                    a = 0
                if b > 24 * 60:
                    b = 24 * 60
                if b > a:
                    paddedBusy.append((a, b))
            busy = paddedBusy

        return {
            "offset": parseOffset(offsetValue),
            "workStart": workStart,
            "workEnd": workEnd,
            "busy": mergeIntervals(busy),
            "free": mergeIntervals(free)
        }

    def freeAt(calendar, userStart, userEnd, userOffset):
