            free.extend(parseIntervalsFromText(fullText, day, "free"))

            if len(busy) == 0 and len(free) == 0:
                if explicitBusy:
                    busy.append((0, 24 * 60))
                elif explicitFree and mode == "free":
                    free.append((0, 24 * 60))

            return busy, free

        fullText = textOf(event)
        busy.extend(parseIntervalsFromText(fullText, day, "busy"))
        free.extend(parseIntervalsFromText(fullText, day, "free"))
        return busy, free

    def loadDay(person, day):
        raw = api.read_calendar(person, day)
        source = chooseData(raw, day)
        offsetValue = pickValue([source, raw], ["utc_offset", "utcOffset", "offset", "time_zone", "timeZone", "timezone"], "+00:00")
        workValue = pickValue([source, raw], ["working_hours", "workingHours", "hours"], "09:00-17:00")

        noteKeys = [
            "note", "notes", "remark", "remarks", "comment", "comments", "memo",
            "message", "description", "details", "info", "constraints", "constraint",
            "blackout", "blackouts", "blackout_rules", "blackoutRules", "rules",
            "rule", "instructions", "instruction", "guidelines", "guideline",
            "preferences", "preference", "policy", "policies", "availability_notes",
            "availabilityNotes", "schedule_notes", "scheduleNotes", "do_not_schedule",
            "doNotSchedule", "blocked_times", "blockedTimes", "title", "summary",
            "subject", "headline", "label", "name"
        ]

        notePieces = []
        for obj in [raw, source]:
            if isinstance(obj, dict):
                for key in noteKeys:
                    if key in obj:
                        piece = textOf(obj.get(key))
                        if piece != "":
                            notePieces.append(piece)
            elif isinstance(obj, str):
                if obj != "":
                    notePieces.append(obj)

        noteText = " ".join(notePieces)

        records = []

        def addValue(value, mode):
            if value is None or value == "":
                return
            if isinstance(value, dict):
                records.append((value, mode))
            elif isinstance(value, list) or isinstance(value, tuple) or isinstance(value, set):
                for item in value:
                    addValue(item, mode)
            else:
                records.append((value, mode))

        for obj in [raw, source]:
            if isinstance(obj, dict):
                for key in ["events", "calendar", "items", "appointments", "blocks", "entries"]:
                    if key in obj:
                        addValue(obj.get(key), None)
                if "busy" in obj:
                    addValue(obj.get("busy"), "busy")
                if "free" in obj:
                    addValue(obj.get("free"), "free")
            elif isinstance(obj, list) or isinstance(obj, tuple) or isinstance(obj, set):
                addValue(obj, None)
            elif isinstance(obj, str):
                addValue(obj, None)

        workStart, workEnd = parseWorkHours(workValue)
        if workEnd <= workStart:
            workEnd += 24 * 60

        busy = []
        free = []
        bufferMinutes = extractBufferMinutes(noteText)

        bufferKeys = ["buffer", "buffer_minutes", "bufferMinutes", "padding", "padding_minutes", "gap", "transition"]
        for obj in [raw, source]:
            if isinstance(obj, dict):
                for key in bufferKeys:
                    if key in obj:
                        value = obj.get(key)
                        if isinstance(value, int) and not isinstance(value, bool):
                            if value > bufferMinutes:
                                bufferMinutes = value
                        else:
                            dur = parseDuration(value)
                            if dur is not None and dur > bufferMinutes:
                                bufferMinutes = dur

        busy.extend(parseIntervalsFromText(noteText, day, "busy"))
        free.extend(parseIntervalsFromText(noteText, day, "free"))

        for item, mode in records:
            eventBusy, eventFree = eventIntervals(item, day, mode)
            busy.extend(eventBusy)
            free.extend(eventFree)

        if bufferMinutes > 0:
            paddedBusy = []
            for start, end in busy:
                a = start - bufferMinutes
                b = end + bufferMinutes
                if a < 0:
                    a = 0
                if b > 24 * 60:
                    b = 24 * 60
                if b > a:
                    paddedBusy.append((a, b))
            busy = paddedBusy

        return {
            "offset": parseOffset(offsetValue),
            "workStart": workStart,
            "workEnd": workEnd,
            "busy": mergeIntervals(busy),
            "free": mergeIntervals(free)
        }

    def freeAt(calendar, userStart, userEnd, userOffset):
        localStart = userStart + calendar["offset"] - userOffset
        localEnd = userEnd + calendar["offset"] - userOffset

        if localStart < calendar["workStart"] or localEnd > calendar["workEnd"]:
            return False

        if len(calendar["free"]) > 0:
            inFree = False
            for freeStart, freeEnd in calendar["free"]:
                if localStart >= freeStart and localEnd <= freeEnd:
                    inFree = True
                    break
            if not inFree:
                return False

        for busyStart, busyEnd in calendar["busy"]:
            if localStart < busyEnd and localEnd > busyStart:
                return False

        return True

    if minutes > 24 * 60:
        return {"starts": {}}

    result = {}
    for day in days:
        userCalendar = loadDay("", day)
        userOffset = userCalendar["offset"]

        userStartBound = userCalendar["workStart"]
        if earliest != "":
            earliestValue = parseAnyTime(earliest)
            if earliestValue is not None and earliestValue > userStartBound:
                userStartBound = earliestValue

        userEndBound = userCalendar["workEnd"] - minutes
        if latest_end != "":
            latestValue = parseAnyTime(latest_end)
            if latestValue is not None:
                latestStart = latestValue - minutes
                if latestStart < userEndBound:
                    userEndBound = latestStart

        userStartBound = ceilQuarter(userStartBound)

        starts = []
        if userStartBound <= userEndBound:
            calendars = [userCalendar]
            for person in attendees:
                calendars.append(loadDay(person, day))

            for start in range(userStartBound, userEndBound + 1, 15):
                if start >= 24 * 60:
                    continue
                end = start + minutes
                if end > 24 * 60:
                    continue
                ok = True
                for calendar in calendars:
                    if not freeAt(calendar, start, end, userOffset):
                        ok = False
                        break
                if ok:
                    starts.append(formatTime(start))

        if len(starts) > 0:
            result[day] = starts

    return {"starts": result}
